-- so re-running the script is a no-op instead of a silent partial write.
INSERT INTO imported_classes (class_id, name, system, markdown, status, created_by)
SELECT 'catyr', 'Catyr', 'rifts', '---
id: catyr
name: Catyr
system: rifts
category: rcc
source_book: Rifts Dimension Book 2: Phase World p.68-69
attribute_dice:
  IQ: "3d6"
  ME: "3d6"
  MA: "3d6"
  PS: "6d6+6"
